<div class="sticker-order-summary" id="sticker-request-<?= (int)$stickerRequest['id'] ?>"><strong>Order #<?php echo (int)$stickerRequest['id']; ?></strong><span><?php echo (int)$stickerRequest['quantity']; ?> sticker(s) · ₱<?php echo number_format((float)$stickerRequest['amount'],2); ?></span>
<?php foreach($requestVehicles as $vehicle): ?><p><?php echo htmlspecialchars($vehicle['plate_number'].' · '.$vehicle['make'].' '.$vehicle['model']); ?><?php if($vehicle['slot_code']): ?> - Slot <strong><?php echo htmlspecialchars($vehicle['slot_code']); ?></strong><?php endif; ?><?php if($vehicle['sticker_number']): ?> · <strong><?php echo htmlspecialchars($vehicle['sticker_number']); ?></strong><?php endif; ?></p><?php endforeach; ?>
<p>Status: <strong><?= htmlspecialchars($stickerRequest['status']==='cancelled' ? 'Cancelled' : ($stickerRequest['claim_status']==='issued' ? 'Issued' : ($stickerRequest['bill_status']==='paid' ? 'Paid / awaiting issuance' : 'Awaiting payment')),ENT_QUOTES,'UTF-8') ?></strong></p>
<?php if ($stickerRequest['status']==='cancelled'): ?><p>This sticker request was cancelled.</p>
<?php elseif ($stickerRequest['claim_status']==='issued'): ?><p>Issued<?php echo $stickerRequest['issued_at']?' on '.htmlspecialchars(date('M j, Y',strtotime($stickerRequest['issued_at']))):''; ?>.<?php if(!$requestVehicles): ?> This historical order needs a vehicle link; contact management after registering your vehicle.<?php endif; ?></p>
<?php elseif($stickerRequest['bill_status']==='paid'): ?><p>Payment verified. Visit management with your receipt to claim your sticker. Issuance is recorded against your approved vehicle.</p>
<?php else: ?><p>Awaiting verified payment. Complete payment from Billing &amp; Payments.</p><a class="service-btn" href="payments.php">Go to billing &amp; payments</a><?php endif; ?></div>
